parameters.jsCode:
const input = $json;

const parentZone = input.parent_timezone;
const tutorZone = 'Asia/Dubai';

// LLM extraction is nested inside "output"
const extracted = input.output;

// -----------------------------
// Normalize written number words
// -----------------------------
function normalizeNumberWords(text) {
  if (!text) return null;

  const numbers = {
    one: '1',
    two: '2',
    three: '3',
    four: '4',
    five: '5',
    six: '6',
    seven: '7',
    eight: '8',
    nine: '9',
    ten: '10',
    eleven: '11',
    twelve: '12'
  };

  let result = text.toLowerCase().trim();

  for (const [word, number] of Object.entries(numbers)) {
    result = result.replace(
      new RegExp(`\\b${word}\\b`, 'g'),
      number
    );
  }

  // Basic support for noon/midnight
  if (result === 'noon') {
    return '12:00 pm';
  }

  if (result === 'midnight') {
    return '12:00 am';
  }

  return result;
}

// -----------------------------
// Parse a parent-local time
// -----------------------------
function parseTime(timeText) {
  if (!timeText) return null;

  const cleaned = normalizeNumberWords(timeText);

  const formats = [
    'h a',      // 5 pm
    'h:mm a',   // 5:30 pm
    'ha',       // 5pm
    'h:mma',    // 5:30pm
    'HH:mm'     // 17:30
  ];

  for (const format of formats) {
    const parsed = DateTime.fromFormat(cleaned, format, {
      zone: parentZone,
      locale: 'en'
    });

    if (parsed.isValid) {
      return {
        hour: parsed.hour,
        minute: parsed.minute
      };
    }
  }

  return null;
}

// -----------------------------
// Normalize weekday wording
// "sundays" -> "sunday"
// -----------------------------
function normalizeDateText(dateText) {
  if (!dateText) return null;

  let text = dateText.trim().toLowerCase();

  const validWeekdays = [
    'monday',
    'tuesday',
    'wednesday',
    'thursday',
    'friday',
    'saturday',
    'sunday'
  ];

  if (text.endsWith('s')) {
    const singular = text.slice(0, -1);

    if (validWeekdays.includes(singular)) {
      text = singular;
    }
  }

  return text;
}

// -----------------------------
// Resolve relative date in
// parent's timezone
// -----------------------------
function resolveDate(dateText, zone) {
  if (!dateText) return null;

  const text = normalizeDateText(dateText);
  const now = DateTime.now().setZone(zone).startOf('day');

  if (text === 'today') {
    return now;
  }

  if (text === 'tomorrow') {
    return now.plus({ days: 1 });
  }

  const weekdays = {
    monday: 1,
    tuesday: 2,
    wednesday: 3,
    thursday: 4,
    friday: 5,
    saturday: 6,
    sunday: 7
  };

  let weekdayText = text;
  let forceNextWeek = false;

  if (text.startsWith('next ')) {
    weekdayText = text.replace('next ', '').trim();
    forceNextWeek = true;
  }

  if (weekdays[weekdayText]) {
    const targetWeekday = weekdays[weekdayText];

    let daysAhead =
      (targetWeekday - now.weekday + 7) % 7;

    // Plain weekday means next occurrence.
    // If today is that weekday, move to next week.
    if (daysAhead === 0) {
      daysAhead = 7;
    }

    // "next Wednesday" explicitly pushes it
    // into the following week.
    if (forceNextWeek && daysAhead < 7) {
      daysAhead += 7;
    }

    return now.plus({ days: daysAhead });
  }

  return null;
}

// -----------------------------
// Build parent-local DateTime
// when both date and time exist
// -----------------------------
function buildDateTime(dateText, timeText) {
  const date = resolveDate(dateText, parentZone);
  const time = parseTime(timeText);

  if (!date || !time) {
    return null;
  }

  return date.set({
    hour: time.hour,
    minute: time.minute,
    second: 0,
    millisecond: 0
  });
}

// -----------------------------
// Build original/requested times
// -----------------------------
const originalParent = buildDateTime(
  extracted.original_date,
  extracted.original_time
);

const requestedParent = buildDateTime(
  extracted.requested_date,
  extracted.requested_time
);

// -----------------------------
// Whole-day search window for
// original session when exact
// original time is missing
// -----------------------------
const originalDateOnly = resolveDate(
  extracted.original_date,
  parentZone
);

const originalSearchStartParent = originalDateOnly
  ? originalDateOnly.startOf('day')
  : null;

const originalSearchEndParent = originalDateOnly
  ? originalDateOnly.plus({ days: 1 }).startOf('day')
  : null;

// -----------------------------
// Return normalized values
// -----------------------------
return [
  {
    json: {
      ...input,

      // Parent-local exact times
      original_start_parent: originalParent
        ? originalParent.toISO()
        : null,

      requested_start_parent: requestedParent
        ? requestedParent.toISO()
        : null,

      // Dubai equivalents
      original_start_dubai: originalParent
        ? originalParent.setZone(tutorZone).toISO()
        : null,

      requested_start_dubai: requestedParent
        ? requestedParent.setZone(tutorZone).toISO()
        : null,

      // Search window for original event
      // Useful when original_time is null
      original_search_start_parent: originalSearchStartParent
        ? originalSearchStartParent.toISO()
        : null,

      original_search_end_parent: originalSearchEndParent
        ? originalSearchEndParent.toISO()
        : null,

      original_search_start_dubai: originalSearchStartParent
        ? originalSearchStartParent.setZone(tutorZone).toISO()
        : null,

      original_search_end_dubai: originalSearchEndParent
        ? originalSearchEndParent.setZone(tutorZone).toISO()
        : null
    }
  }
];

