const items = $input.all();

// ---------- CONFIG ----------
const tutorZone = 'Asia/Dubai';

const weekdayStartHour = 15; // 3 PM
const weekdayEndHour = 20;   // 8 PM

const weekendStartHour = 10; // 10 AM
const weekendEndHour = 20;   // 8 PM

const slotStepMinutes = 30;
const maxAlternatives = 3;
// ----------------------------

// Pull request data from Build Approval Data
const approval = $('Build Approval Data').item.json;

const requestedStart = DateTime
  .fromISO(approval.requested_start_datetime)
  .setZone(tutorZone);

const durationMinutes = Number(approval.duration_minutes);

const parentTimezone = approval.parent_timezone;

// Convert Calendar events into busy ranges
const busyRanges = items
  .map(item => {
    const start = item.json.start?.dateTime;
    const end = item.json.end?.dateTime;

    if (!start || !end) return null;

    return {
      start: DateTime.fromISO(start).setZone(tutorZone),
      end: DateTime.fromISO(end).setZone(tutorZone),
      summary: item.json.summary ?? ''
    };
  })
  .filter(Boolean);

// Check if proposed slot overlaps a busy event
function overlapsBusy(slotStart, slotEnd) {
  return busyRanges.some(event => {
    return slotStart < event.end && slotEnd > event.start;
  });
}

// Generate alternatives
const alternatives = [];

// Start from requested day/time, but move forward in time.
// Search for up to 7 calendar days.
const searchStartDay = requestedStart.startOf('day');

for (let dayOffset = 0; dayOffset < 7; dayOffset++) {
  const day = searchStartDay.plus({ days: dayOffset });

  // Luxon weekday: Mon = 1 ... Sun = 7
  const isWeekend = day.weekday === 6 || day.weekday === 7;

  const startHour = isWeekend
    ? weekendStartHour
    : weekdayStartHour;

  const endHour = isWeekend
    ? weekendEndHour
    : weekdayEndHour;

  let candidateStart = day.set({
    hour: startHour,
    minute: 0,
    second: 0,
    millisecond: 0
  });

  const dayBoundary = day.set({
    hour: endHour,
    minute: 0,
    second: 0,
    millisecond: 0
  });

  while (candidateStart.plus({ minutes: durationMinutes }) <= dayBoundary) {
    const candidateEnd = candidateStart.plus({
      minutes: durationMinutes
    });

    // Don't suggest the exact rejected slot
    const isOriginalRequestedSlot =
      candidateStart.toMillis() === requestedStart.toMillis();

    // Don't suggest anything already in the past
    const isFuture =
      candidateStart > DateTime.now().setZone(tutorZone);

    if (
      !isOriginalRequestedSlot &&
      isFuture &&
      !overlapsBusy(candidateStart, candidateEnd)
    ) {
      const parentStart = candidateStart.setZone(parentTimezone);
      const parentEnd = candidateEnd.setZone(parentTimezone);

      alternatives.push({
        dubai_start: candidateStart.toISO(),
        dubai_end: candidateEnd.toISO(),

        dubai_display:
          `${candidateStart.toFormat("ccc, dd LLL • h:mm a")}–` +
          `${candidateEnd.toFormat("h:mm a")}`,

        parent_start: parentStart.toISO(),
        parent_end: parentEnd.toISO(),

        parent_display:
          `${parentStart.toFormat("cccc, dd LLLL yyyy 'at' h:mm a")}–` +
          `${parentEnd.toFormat("h:mm a")}`,

        parent_timezone: parentTimezone
      });

      if (alternatives.length >= maxAlternatives) {
        break;
      }
    }

    candidateStart = candidateStart.plus({
      minutes: slotStepMinutes
    });
  }

  if (alternatives.length >= maxAlternatives) {
    break;
  }
}

return [
  {
    json: {
      requested_start_datetime: approval.requested_start_datetime,
      duration_minutes: durationMinutes,
      parent_timezone: parentTimezone,
      alternatives_found: alternatives.length,
      alternatives
    }
  }
];

